<?php
require 'config.php';require_login();verify_csrf();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$path=upload_file('document',['pdf','jpg','jpeg','png'],'loads');if(!$path)throw new RuntimeException('Choose a file to upload.');$s=db()->prepare("INSERT INTO load_documents(load_id,document_type,file_path,original_name) VALUES(?,?,?,?)");$s->execute([(int)$_POST['load_id'],$_POST['document_type'],$path,$_FILES['document']['name']]);flash('success','Load document uploaded.');redirect('documents.php');}catch(Throwable $e){$error=$e->getMessage();}}
$loads=db()->query("SELECT id,load_no FROM loads ORDER BY id DESC")->fetchAll();$rows=db()->query("SELECT ld.*,l.load_no FROM load_documents ld JOIN loads l ON l.id=ld.load_id ORDER BY ld.id DESC")->fetchAll();$pageTitle='Load Documents';$active='documents';require 'partials_header.php';?>
<div class="page-head"><div><h1>BOL, POD & load documents</h1><p>Upload and retrieve signed load paperwork and rate confirmations.</p></div></div><div class="form-card" style="margin-bottom:20px"><h3>Upload document</h3><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field"><label>Load</label><select name="load_id" required><?php foreach($loads as $l):?><option value="<?=$l['id']?>"><?=e($l['load_no'])?></option><?php endforeach;?></select></div><div class="field"><label>Document type</label><select name="document_type"><option>BOL</option><option>POD</option><option>Rate Confirmation</option><option>Other</option></select></div><div class="field full"><label>File (PDF/JPG/PNG, max 15MB)</label><input type="file" name="document" required accept=".pdf,.jpg,.jpeg,.png"></div></div><div class="form-actions"><button class="btn primary">Upload document</button></div></form></div><div class="table-wrap"><table class="table"><thead><tr><th>Load</th><th>Type</th><th>Original filename</th><th>Uploaded</th><th>File</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['load_no'])?></td><td><?=e($r['document_type'])?></td><td><?=e($r['original_name'])?></td><td><?=e($r['uploaded_at'])?></td><td><a target="_blank" href="<?=e($r['file_path'])?>">Open document</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty">No documents uploaded.</td></tr><?php endif;?></tbody></table></div><?php require 'partials_footer.php';?>